  items: [
    { id: 'a3', title: 'Policy approved', tone: 'success', time: instant(Date.UTC(2026, 10, 23, 14, 5)), avatar: { name: 'Ada Lovelace' } },
    { id: 'a2', title: 'Review requested', tone: 'info', time: instant(Date.UTC(2026, 10, 23, 9, 30)), actions: [{ id: 'open', label: 'Open review' }] },
    { id: 'a1', title: 'Draft uploaded', time: instant(Date.UTC(2026, 10, 20, 16, 0)), description: 'leave-policy.docx, 48 kB' },
  ],
});
host.addEventListener('aui-action', (event) => {
  const { itemId, actionId } = (event as CustomEvent<TimelineActionDetail>).detail;
