});

import { instant } from '@absoluteui/core';
import { Timeline, type TimelineItem } from '@absoluteui/components/timeline';

const host = document.createElement('div');
document.body.append(host);
const start = Date.UTC(2026, 10, 23, 12);
const page = (from: number): TimelineItem[] => Array.from({ length: 10 }, (_, i) => ({ id: `e${String(from + i)}`, title: `Event ${String(from + i)}`, time: instant(start - (from + i) * 3_600_000) }));
let loaded = 10;
Timeline.create(host, {
  label: 'Audit log',
  timeFormat: 'relative',
  now: instant(start),
  items: page(0),
  initialVisible: 5,
  loadMore: async ({ signal }) => {
    await new Promise((resolve) => setTimeout(resolve, 100));
    if (signal.aborted) return [];
    const next = loaded < 30 ? page(loaded) : [];
    loaded += next.length;
    return next;
  },
});

